//! The XTGETTCAP table the terminal answers from, generated from vtium's
//! terminfo entry, `install/xterm-vtium.ti`.
//!
//! The table is compiled in: `table.rs` is generated by the test
//! `table_matches_the_entry`, which fails when the committed table differs
//! from the entry (`VTIUM_BLESS=1` rewrites it), as the C reference's
//! `termcap_drift` did. Each string is as ncurses' `tigetstr` gives it:
//! escapes decoded to their bytes, `%` sequences and padding as written; a
//! number is its decimal text, and a boolean has no value.
//!
//! Beside the entry's capabilities the table carries the names xterm's
//! XTGETTCAP answers that are no terminfo capability: `TN` and `name`, the
//! entry's name, and `Co`, termcap's `colors`. `cols` and `lines` are left
//! out: they give a default size, and a program asking the terminal wants
//! the real one, which `TIOCGWINSZ` reports.
//!
//! The table describes vtium's entry alone, so a terminal answers from it
//! only while its session's `TERM` is the entry's name, [`NAME`]. Under any
//! other `TERM`, `kmscon` included, the entry the session finds is another
//! one, and every name is unknown. The C reference gave its table only to a
//! terminal whose session had its own entry's name, `kmscon`
//! (`src/terminal_vte.c:36-56` at kmscon origin/main).

mod table;
#[cfg(test)]
mod terminfo;

use vtium_term::{Termcap, TermcapError};

/// The name of vtium's terminfo entry, the default `TERM`.
pub const NAME: &str = "xterm-vtium";

/// The table's capabilities, each name with its value, none for a
/// boolean, sorted by name.
pub fn entries() -> &'static [(&'static str, Option<&'static [u8]>)] {
    table::TABLE
}

/// The table, for [`vtium_term::Terminal::set_termcap`].
pub fn termcap() -> Result<Termcap, TermcapError> {
    Termcap::new(
        table::TABLE
            .iter()
            .map(|(name, value)| (name.as_bytes(), *value)),
    )
}

/// The table for a session whose `TERM` is `term`: vtium's under
/// [`NAME`], and none under any other name.
pub fn for_term(term: &str) -> Option<Result<Termcap, TermcapError>> {
    (term == NAME).then(termcap)
}
